'use strict';
// 审阅用原型：所有任务只在内存中；禁止业务API、真实模型和Office生成调用。
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tasks = [
  {id:'probability',title:'条件概率：从直觉到判断',course:'数学 · 高一',audience:'高一学生，已学习古典概型',minutes:45,content:'用抽球、天气与出行等生活情境理解条件概率，区分条件概率与独立事件。安排一道例题和两道课堂练习。',status:'complete',method:'auto',skill:'PPT Master',files:[],version:1,selectedSlide:0,confirmed:true},
  {id:'information',title:'信息与数据：从生活中发现规律',course:'信息技术 · 七年级',audience:'七年级学生，具备基本计算机操作能力',minutes:40,content:'认识数据与信息的区别，用校园气温记录设计一个课堂活动。',status:'outline',method:'auto',skill:'PPT Master',files:[],version:0,selectedSlide:0},
  {id:'reading',title:'阅读一篇说明文',course:'语文 · 八年级',audience:'八年级学生',minutes:45,content:'通过一篇说明文学习说明顺序与说明方法，安排随堂练习。',status:'draft',method:'manual',skill:'PPT Master',files:[],version:0,selectedSlide:0},
  {id:'energy',title:'能量的转化与守恒',course:'物理 · 九年级',audience:'九年级学生',minutes:45,content:'以生活中的能量转化为例，认识能量守恒定律，设计一项讨论和一组练习。',status:'failed',method:'auto',skill:'WorkBuddy 内置 PPT',files:[],version:0,selectedSlide:0}
];
let currentId=null, fresh=null, query='', courseFilter='', toastTimer, runCounter=0;
const statuses={draft:['草稿',''],outline:['待确认大纲','amber'],submitting:['交接中','blue'],generating:['制作中','blue'],complete:['待检查','blue'],ready:['可上课','green'],failed:['交接失败','red'],cancelled:['已取消',''],manual:['外部制作中','amber']};
function task(){return tasks.find(t=>t.id===currentId)||fresh;}
function tag(t){const [label,color]=statuses[t.status]||statuses.draft;return `<span class="tag ${color}">${label}</span>`;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function modal(title,body,actions=''){ $('modalContent').innerHTML=`<button class="modal-close" data-action="close" aria-label="关闭弹窗">×</button><h2 id="modalTitle">${title}</h2>${body}<div class="modal-actions">${actions||'<button data-action="close">知道了</button>'}</div>`;$('modal').showModal();}
function close(){ $('modal').close(); }
function route(view,id){location.hash=view==='list'?'list':view==='new'?'new':`task/${id||currentId}/${view}`;}
function ensureTask(){const t=task();if(!tasks.includes(t))tasks.unshift(t);currentId=t.id;return t;}
function invalidate(t){stopRun(t);t.confirmed=false;t.reviewed=false;t.status='draft';t.outlineRevision=0;t.outlineNote='';t.outlineTitles=null;t.changes={};t.changeDrafts={};t.pendingChange=null;t.lastChange='';}
function newTask(){return {id:'demo-'+Date.now(),title:'',course:'',audience:'',minutes:45,content:'',files:[],status:'draft',method:'auto',skill:'PPT Master',version:0,selectedSlide:0};}
function render(){
  const parts=location.hash.slice(1).split('/');
  if(parts[0]==='new'){if(!fresh||tasks.includes(fresh))fresh=newTask();currentId=fresh.id;renderRequirements();}
  else if(parts[0]==='task'&&tasks.some(t=>t.id===parts[1])){currentId=parts[1];const view=parts[2];if(view==='requirements')renderRequirements();else if(view==='method')renderMethod();else if(view==='manual')renderManual();else renderFeedback();}
  else renderList();
  $('main').scrollTop=0;
}
function listRows(){
  const found=tasks.filter(t=>(!courseFilter||t.course===courseFilter)&&(!query||(t.title+' '+t.course).toLowerCase().includes(query.toLowerCase())));
  $('taskRows').innerHTML=found.length?found.map((t,i)=>`<article class="task-row"><div class="task-title"><div class="thumb ${i===2?'paper':i===1?'sage':''}" aria-hidden="true"><span>一堂课 / 课前准备</span><b>${String(i+1).padStart(2,'0')}</b></div><div><strong>${esc(t.title||'未命名课件')}</strong><small>${t.minutes} 分钟 · ${t.version?'6页示意 · 版本 '+t.version:'教学课件'}</small></div></div><span class="course-col muted">${esc(t.course||'未关联课程')}</span><div class="status-col">${tag(t)}</div><span class="method-col muted">${t.method==='auto'?'平台调用':'手动调用'}</span><span class="updated-col muted">${i===0?'今天 14:20':'今天 10:30'}</span><div class="operation-col"><button class="small ${i===0?'primary':''}" data-action="open" data-id="${t.id}">${['complete','ready'].includes(t.status)?'查看课件':t.status==='draft'?'继续填写':'查看进度'}</button></div></article>`).join(''):`<div class="empty-state"><h3>没有找到课件</h3><p>试试其他关键词或课程。</p></div>`;
  $('resultCount').textContent=`共 ${found.length} 份课件`;
}
function renderList(){
  $('view').innerHTML=`<div class="content-width"><header class="page-head"><div><p class="subline">从教学想法到课堂演示，让每一页都有重点。</p></div><button class="primary" data-action="new">＋ 新建课件</button></header>
  <section class="welcome"><div><h2>填一份要求，选择适合你的制作方式</h2><p>可以复制给 WorkBuddy 独立制作，也可以在这里交接、确认大纲和接收课件。</p></div><div class="mini-flow"><span><b>01</b>填写要求</span><i>→</i><span><b>02</b>确认大纲</span><i>→</i><span><b>03</b>检查课件</span></div></section>
  <div class="toolbar"><input id="search" class="search" placeholder="搜索课件名称" aria-label="搜索课件" value="${esc(query)}"><select id="filter" aria-label="筛选课程"><option value="">全部课程</option>${[...new Set(tasks.map(t=>t.course).filter(Boolean))].map(c=>`<option ${c===courseFilter?'selected':''}>${esc(c)}</option>`).join('')}</select><span class="count" id="resultCount"></span></div>
  <section class="task-list"><div class="table-head"><span>课件名称</span><span class="course-col">课程</span><span>状态</span><span class="method-col">制作方式</span><span class="updated-col">更新时间</span><span>操作</span></div><div id="taskRows"></div></section><p class="list-footer">◷ <span>任务与历史版本留在这里，随时继续制作。</span></p></div>`;
  listRows();$('search').oninput=e=>{query=e.target.value;listRows();};$('filter').onchange=e=>{courseFilter=e.target.value;listRows();};
}
function shell(step){const t=task();return `<div class="content-width"><nav class="breadcrumb" aria-label="面包屑"><button data-action="list">PPT管理</button><span>/</span><span>${esc(t.title||'新建课件')}</span></nav><header class="page-head"><div><h1>${step===1?'新建课件':esc(t.title)}</h1><p class="subline">${step===1?'先告诉我们这节课要讲什么。':'要求只填一次，手动与平台调用共用。'}</p></div>${step===3?`<div class="head-actions">${tag(t)}<button class="small" data-action="list">返回列表</button></div>`:''}</header><div class="flow-navigation"><nav class="flow-steps" aria-label="制作流程">${['填写要求','选择方式','制作与反馈'].map((s,i)=>`<div class="flow-step ${i+1===step?'active':i+1<step?'complete':''}" ${i+1===step?'aria-current="step"':''}><i class="flow-number">${i+1}</i>${s}</div>`).join('')}</nav></div>`;}
function previousFooter(step){return `<div class="flow-footer"><button class="flow-back" data-action="previous" data-step="${step}" ${['submitting','generating'].includes(task().status)?'disabled':''}>← 上一步</button></div>`;}
function renderRequirements(){
  const t=task();$('view').innerHTML=shell(1)+`<div class="form-layout"><section class="panel"><div class="panel-heading"><h2>这节课的要求</h2><button class="text-button" data-action="example">填入示例</button></div><form id="requirements" novalidate><div class="fields">
  <div class="field wide"><label for="title">本课主题</label><input id="title" maxlength="80" placeholder="例如：条件概率，从生活情境理解数学" value="${esc(t.title)}" required></div>
  <div class="field"><label for="audience">授课对象</label><input id="audience" maxlength="100" placeholder="例如：高一，已学习古典概型" value="${esc(t.audience)}" required></div>
  <div class="field"><label for="minutes">课时 <em>分钟</em></label><input id="minutes" type="number" min="5" max="240" value="${t.minutes}" required></div>
  <div class="field wide"><label for="content">教学内容或参考资料</label><textarea id="content" maxlength="12000" placeholder="简单写下要讲的知识点、使用的教材章节或课堂安排；也可以在下方附上资料。">${esc(t.content)}</textarea><p class="helper">写内容或附资料，选一种即可。教学目标与大纲会在制作前请你确认。</p></div>
  <div class="field wide"><label class="upload" id="dropzone" for="files" tabindex="0" role="button" aria-label="选择参考资料"><span aria-hidden="true">⇧</span><div><strong>点击或拖入参考资料</strong><p>PDF、Word、PPTX、TXT、Markdown、图片 · 每份不超过20MB</p></div></label><input id="files" type="file" hidden multiple accept=".pdf,.docx,.pptx,.txt,.md,.png,.jpg,.jpeg"><div id="fileList" class="file-list"></div><p class="helper">原型仅显示文件名，不读取或上传文件内容。</p></div></div>
  <details class="optional"><summary>补充要求 <span class="muted">（可选）</span></summary><div class="fields"><div class="field"><label for="course">关联课程</label><select id="course"><option value="">暂不关联</option>${['数学 · 高一','信息技术 · 七年级','语文 · 八年级','物理 · 九年级'].map(c=>`<option ${t.course===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="style">视觉风格</label><select id="style">${['清晰简洁，适合投影','温暖人文','蓝白学术'].map(s=>`<option ${s===t.style?'selected':''}>${s}</option>`).join('')}</select></div><div class="field wide"><label for="extra">还有什么希望注意的？</label><input id="extra" placeholder="例如：重点讲清易错点，练习答案放教师备注" value="${esc(t.extra)}" maxlength="500"></div></div></details><p class="error-text" id="formError" role="alert"></p><div class="savebar"><button type="button" class="text-button" data-action="list">返回列表</button><div><span class="save-hint">当前页面内保存</span><button type="button" data-action="save">保存草稿</button><button type="submit" class="primary">下一步：选择制作方式 →</button></div></div></form></section>
  <aside class="aside-note"><h3>只填必要的，剩下交给 WorkBuddy</h3><ul><li>主题、对象和课时决定教学节奏。</li><li>有参考资料就附上，没有也可以直接写内容。</li><li>先确认大纲，再制作完整课件。</li></ul><div class="stack-note"><h3>让课件更贴近你的课堂</h3><p>可以补充学生已有的知识、常见错误，或想重点讨论的问题。无需写很长的提示词。</p></div></aside></div></div>`;
  for(const key of ['title','audience','minutes','content','course','style','extra'])$(key).addEventListener('input',e=>{invalidate(t);t[key]=key==='minutes'?Number(e.target.value):e.target.value;});
  $('requirements').onsubmit=e=>{e.preventDefault();if(validate()){ensureTask();route('method');}};
  $('files').onchange=e=>addFiles(e.target.files);const zone=$('dropzone');zone.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('files').click();}};zone.ondragover=e=>{e.preventDefault();zone.classList.add('dragover');};zone.ondragleave=()=>zone.classList.remove('dragover');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('dragover');addFiles(e.dataTransfer.files);};renderFiles();
}
function validate(){const t=task();let msg='';if(!t.title.trim())msg='请填写本课主题。';else if(!t.audience.trim())msg='请填写授课对象。';else if(!Number.isFinite(t.minutes)||t.minutes<5||t.minutes>240)msg='课时请填写5至240分钟。';else if(!t.content.trim()&&!t.files.length)msg='请填写教学内容，或附上一份参考资料。';if($('formError'))$('formError').textContent=msg;if(msg){const field=!t.title.trim()?'title':!t.audience.trim()?'audience':t.minutes<5||t.minutes>240?'minutes':'content';$(field)?.focus();}return !msg;}
function addFiles(files){const t=task();for(const f of files){if(t.files.length>=10){toast('最多选择10份参考资料。');break;}if(f.size>20*1024*1024){toast(f.name+' 超过20MB，请换一份资料。');continue;}if(!/\.(pdf|docx|pptx|txt|md|png|jpe?g)$/i.test(f.name)){toast('请选择支持的资料格式。');continue;}if(!t.files.some(x=>x.name===f.name)){invalidate(t);t.files.push({name:f.name,size:f.size});}}renderFiles();}
function renderFiles(){if($('fileList'))$('fileList').innerHTML=task().files.map((f,i)=>`<span class="file-chip">▤ ${esc(f.name)}<button data-action="remove-file" data-index="${i}" type="button" aria-label="移除 ${esc(f.name)}">×</button></span>`).join('');}
function renderMethod(){const t=task();$('view').innerHTML=shell(2)+`<div class="form-layout"><section class="panel"><div class="panel-heading"><h2>选择制作方式</h2><span class="index">同一份教学要求</span></div><div class="method-grid"><button class="method-card ${t.method==='auto'?'selected':''}" data-action="method" data-method="auto" aria-pressed="${t.method==='auto'}"><span class="radio"></span><span class="method-icon">↗</span><h3>平台调用</h3><p>在这里交给 WorkBuddy 制作，<br>确认大纲、查看反馈、接收课件。</p><span class="method-foot">无需切换应用 · 需要可用连接</span></button><button class="method-card ${t.method==='manual'?'selected':''}" data-action="method" data-method="manual" aria-pressed="${t.method==='manual'}"><span class="radio"></span><span class="method-icon">▤</span><h3>手动调用</h3><p>复制完整任务文本，<br>单独发给 WorkBuddy 制作与修改。</p><span class="method-foot">保底方式 · 随时可以使用</span></button></div>
  <div class="callout ${t.method==='auto'?'':'amber'}" style="margin-top:18px">${t.method==='auto'?'◉ 本次体验会模拟 WorkBuddy 交接，不建立真实连接，也不消耗模型额度。':'↗ 提示词与填写内容会合并好。打开 WorkBuddy 后粘贴，再附上原始资料即可。'}</div>
  <details class="optional"><summary>制作设置 <span class="muted">（已有默认配置，无需修改）</span></summary><div class="skill-row"><label for="skill" style="margin:0">制作技能</label><select id="skill"><option ${t.skill==='PPT Master'?'selected':''}>PPT Master</option><option ${t.skill==='WorkBuddy 内置 PPT'?'selected':''}>WorkBuddy 内置 PPT</option><option disabled>Dashi PPT（待许可评估）</option></select><span>候选技能仅供原型展示，尚未安装或验证。</span></div></details>
  <div class="savebar"><button class="text-button" data-action="requirements">← 上一步</button><button class="primary" data-action="start">${t.method==='auto'?'模拟交给 WorkBuddy →':'查看可复制的任务文本 →'}</button></div><p class="next-note">${t.method==='auto'?'实际使用时，所选资料将交由 WorkBuddy 的模型服务处理，调用按账号配置计费。':'手动调用同样需要 WorkBuddy 可用；制作过程与反馈在独立对话中完成。'}</p></section><aside class="aside-note"><h3>已填写的要求</h3><dl class="input-review"><dt>本课主题</dt><dd>${esc(t.title)}</dd><dt>授课对象</dt><dd>${esc(t.audience)}</dd><dt>课时</dt><dd>${t.minutes} 分钟</dd><dt>参考资料</dt><dd>${t.files.length?t.files.length+' 份资料':'已填写教学内容'}</dd></dl><div class="stack-note"><h3>两种方式，目标一致</h3><p>先确认教学大纲，再制作可编辑 PPTX。不满意时，告诉 WorkBuddy 要改哪一页。</p></div></aside></div></div>`;$('skill').onchange=e=>t.skill=e.target.value;}
function promptText(t){return `请根据以下要求制作一节课的教学PPT，使用 ${t.skill} 技能；若不可用，先说明缺少什么。\n\n先给出教学目标、内容顺序与时间分配的大纲，等我确认后再制作。课件适合投影，按教学需要安排讲解、例题或练习、总结。教师备注与学生可见内容分开，练习答案默认放教师备注。核对事实和答案，不编造资料来源。\n\n请交付可编辑的PPTX，并说明哪些元素仍是图片。保留制作源文件，便于指定页面修改。失败时说明已完成内容、失败阶段与继续方法。\n\n【教学要求】\n本课主题：${t.title}\n授课对象：${t.audience}\n课时：${t.minutes} 分钟\n教学内容：${t.content||'请根据附件整理'}\n参考资料：${t.files.length?t.files.map(f=>f.name).join('、'):'无额外附件'}\n视觉风格：${t.style||'清晰简洁，适合投影'}${t.extra?'\n补充要求：'+t.extra:''}\n\n${t.files.length?'我会另外附上上述原始资料。请先确认能否读取，不要仅根据文件名猜测内容。':'请先给出建议大纲，待我确认。'}`;}
function sideInfo(t){return `<aside class="aside-note"><div><h3>本次制作</h3><dl class="facts"><dt>方式</dt><dd>${t.method==='auto'?'平台调用（模拟）':'手动调用'}</dd><dt>课时</dt><dd>${t.minutes} 分钟</dd><dt>技能</dt><dd>${esc(t.skill)}</dd><dt>资料</dt><dd>${t.files.length?t.files.length+' 份':'文字内容'}</dd></dl><button class="text-button side-action" data-action="inspect">查看教学要求</button></div><div class="stack-note"><h3>需要换一种方式？</h3><p>${t.method==='auto'?'平台交接不顺利时，可以复制同样的要求，单独交给 WorkBuddy。':'你可以在外部完成制作，回来保存课件记录；无需在平台重复填写。'}</p><button class="side-action" data-action="${t.method==='auto'?'switch-manual':'import'}">${t.method==='auto'?'改用手动调用':'导回课件记录'}</button></div>${t.method==='auto'?`<details class="review-controls"><summary>原型状态演示</summary><div><button data-action="simulate-fail">连接失败</button><button data-action="simulate-cancel">已取消</button><button data-action="simulate-outline">待确认大纲</button></div></details>`:''}</aside>`;}
function renderManual(){const t=task();$('view').innerHTML=shell(3)+`<div class="workspace"><section class="panel"><div class="panel-heading"><h2>复制后，交给 WorkBuddy</h2><span class="tag">手动调用</span></div><div class="manual-checklist"><div><b>01</b><strong>复制完整任务</strong><p>教学要求已合并到提示词中。</p></div><div><b>02</b><strong>在 WorkBuddy 粘贴</strong><p>新建对话，再附上原始资料。</p></div><div><b>03</b><strong>确认大纲与成品</strong><p>在独立对话中继续修改课件。</p></div></div><label for="prompt">任务文本 <em>可直接复制，无需自己写提示词</em></label><textarea class="prompt-box" id="prompt" readonly>${esc(promptText(t))}</textarea><div class="manual-actions"><button class="primary" data-action="copy">复制完整任务</button><button data-action="download-text">下载任务文本</button><button class="text-button" data-action="requirements">修改要求</button></div><div class="callout" style="margin-top:20px">${t.files.length?'附件不会随文本一起复制，请在 WorkBuddy 中另外附上 '+t.files.length+' 份原始资料。':'需要更准确地依据教材制作时，可以另外在 WorkBuddy 附上教材或参考资料。'}</div><hr class="divider"><div class="savebar"><p class="muted">${t.status==='manual'?'✓ 已标记为外部制作中，结果请在 WorkBuddy 查看。':'发出后可标记进度，方便下次回来继续。'}</p><button data-action="manual-sent" ${t.status==='manual'?'disabled':''}>${t.status==='manual'?'已交给 WorkBuddy':'我已交给 WorkBuddy'}</button></div>${t.importedName?`<div class="message">已记录示例文件：${esc(t.importedName)}。本原型未上传或解析文件。</div>`:''}</section>${sideInfo(t)}</div>${previousFooter(3)}</div>`;}
function getOutline(t){const names=t.outlineTitles||['情境导入：先做一个直觉判断','核心概念：把条件说清楚','例题讲解：一步一步分析','课堂练习：判断并解释理由','回顾总结：带走三个要点'];const ratios=[.11,.27,.24,.27,.11];let used=0;return names.map((title,i)=>{const minutes=i===4?t.minutes-used:Math.round(t.minutes*ratios[i]);used+=minutes;return {title,minutes,desc:['联系生活经验，提出本课问题','结合材料解释概念，突出易错点','通过例题展示分析过程','独立思考、同伴讨论与教师讲评','回扣教学目标，检查理解情况'][i]};});}
function outlineCard(t){return `<section class="outline"><div class="outline-head"><h2>${t.outlineRevision?'已按补充要求调整的大纲':'这节课，建议这样讲'}</h2><p>请先检查内容顺序与时间，再开始制作。</p></div><p class="objective"><strong>建议目标</strong>　${esc(t.objective||'能够解释本课核心概念，在情境中应用，并说出自己的判断依据。')}<br><span class="muted">演示大纲仅用于交互审阅，不代表对当前材料的真实分析。</span></p>${getOutline(t).map((o,i)=>`<div class="outline-row"><span class="num">0${i+1}</span><div><strong>${esc(o.title)}</strong><p>${o.desc}</p></div><span class="duration">${o.minutes} 分钟</span></div>`).join('')}<div class="outline-actions"><button class="text-button" data-action="edit-outline">调整大纲</button><p>合计 ${t.minutes} 分钟 · 将保留教师备注</p><button class="primary" data-action="confirm-outline">确认大纲，开始模拟制作</button></div></section><form class="feedback-form" id="outlineFeedback"><input id="outlineNote" aria-label="大纲补充要求" placeholder="补充一句要求，例如：减少概念讲解，增加课堂练习" maxlength="500"><button type="submit">发送调整建议</button></form>`;}
function renderFeedback(){const t=task();let body='';
  if(t.status==='outline')body=`<section class="panel"><div class="panel-heading"><h2>WorkBuddy 反馈</h2><span class="muted">示例反馈</span></div><div class="timeline"><span class="check">✓</span><div><strong>教学要求已交接</strong><p>${t.files.length?t.files.length+' 份参考资料及':'已填写的'}教学要求已整理为一项制作任务。</p></div><time>刚刚</time></div>${t.outlineNote?`<div class="message teacher">你的补充：${esc(t.outlineNote)}</div>`:''}${outlineCard(t)}</section>`;
  else if(['submitting','generating'].includes(t.status))body=`<section class="panel status-card"><div class="status-symbol">${t.status==='submitting'?'↗':'▧'}</div><h2>${t.status==='submitting'?'正在模拟交接教学要求':'正在模拟制作课件'}</h2><p>${t.status==='submitting'?'接下来会展示待确认的大纲。':'大纲已确认，正在模拟内容整理、排版与页面检查。'}<br>你可以返回列表，任务会在当前页面内继续。</p><div class="progress-track" aria-label="模拟制作进行中"><span></span></div><div class="status-actions"><button data-action="list">返回列表</button><button class="danger" data-action="cancel">取消本次制作</button></div></section>`;
  else if(['failed','cancelled'].includes(t.status))body=`<section class="panel status-card error-card"><div class="status-symbol">${t.status==='failed'?'!':'Ⅱ'}</div><h2>${t.status==='failed'?'暂时没能交给 WorkBuddy':'本次制作已取消'}</h2><p>${t.status==='failed'?'模拟原因：连接或登录不可用。教学要求已保留。':'教学要求与已有版本仍保留，可以稍后继续。'}<br>没有自动重试或消耗真实模型额度。</p><div class="status-actions"><button class="primary" data-action="retry">${t.status==='failed'?'模拟重试':'继续模拟制作'}</button><button data-action="switch-manual">改用手动调用</button></div></section>`;
  else body=deckCard(t);
  $('view').innerHTML=shell(3)+`<div class="workspace">${body}${['complete','ready'].includes(t.status)?resultSide(t):sideInfo(t)}</div>${previousFooter(3)}</div>`;
  if(['complete','ready'].includes(t.status)){
    positionChangeEditor();
    $('changeText').oninput=e=>{t.changeDrafts||={};t.changeDrafts[t.selectedSlide||0]=e.target.value;};
    $('changeSlide').onchange=e=>{t.selectedSlide=Number(e.target.value);renderFeedback();};
  }
  if($('outlineFeedback'))$('outlineFeedback').onsubmit=e=>{e.preventDefault();const note=$('outlineNote').value.trim();if(!note)return; t.outlineNote=note;renderFeedback();toast('调整建议已记录。原型不调用模型，可通过“调整大纲”编辑示例内容。');};
}
const slideExamples=[
  {title:'从直觉出发，学会有依据地判断',points:[],notes:'用一个学生熟悉的生活问题开场，先收集直觉判断，不急着公布答案。'},
  {title:'同一个问题，条件变了',points:['先说出你观察到的条件','讨论：新增信息会改变判断吗？','把直觉与理由分别写下来'],notes:'请学生先独立思考，再与同桌交换理由。关注判断时忽略了哪些前提。'},
  {title:'先理解概念，再选择方法',points:['明确本课的核心概念','区分适用条件与常见误解','用一句话解释你的理解'],notes:'此页为内容占位示意。正式制作时应根据教学材料填写准确的概念与公式，并由教师核对。'},
  {title:'一起拆解一道例题',points:['读题：已知什么，要求什么？','分析：找出关键条件与关系','检验：答案能否解释原来的问题？'],notes:'留出学生尝试的时间。可用提问逐步揭示分析过程，避免一开始展示完整答案。'},
  {title:'轮到你来解释',points:['独立完成一个相似情境','向同伴解释你的判断依据','交流不同做法，检查易错点'],notes:'练习答案与讲评要点默认放在教师备注。这里是交互原型，未生成真实题目或答案。'},
  {title:'今天，我们带走什么',points:['一个概念：用自己的话说清楚','一种方法：说明什么时候适用','一个提醒：不要遗漏关键条件'],notes:'回到开场问题，让学生修正或补充最初的判断，以检查本课目标是否达成。'}
];
function deckCard(t){const n=t.selectedSlide||0,s=slideExamples[n],title=n===0?t.title:t.changes?.[n]?.title||s.title;return `<section class="panel"><div class="panel-heading"><div><h2>${t.status==='ready'?'课件已标记可上课':'课件交付示意'}</h2><p class="helper">${t.version>1?'已完成局部修改示意 · 版本 '+t.version:'先检查每一页，再用于实际课堂。'}</p></div><span class="tag ${t.status==='ready'?'green':'blue'}">${t.status==='ready'?'已检查（模拟）':'待教师检查'}</span></div><div class="deck-workspace"><nav class="slide-list" aria-label="课件页面">${slideExamples.map((s,i)=>`<button class="slide-item ${n===i?'active':''}" data-action="slide" data-index="${i}" aria-pressed="${n===i}"><span class="slide-mini"><span>${i===0?'本课主题':s.title.slice(0,7)}</span><b>0${i+1}</b></span>0${i+1} · ${['封面','导入','概念','例题','练习','总结'][i]}</button>`).join('')}</nav><div class="deck-main"><div class="slide ${n===0?'cover':''}"><div class="eyebrow">${n===0?'LESSON / 课堂学习':['','START WITH A QUESTION','UNDERSTAND THE CONCEPT','WORK THROUGH AN EXAMPLE','TRY IT YOURSELF','TAKEAWAYS'][n]}</div><h2>${esc(title)}</h2>${n===0?`<p class="deck-sub">${esc(t.audience)}<br>${t.minutes} 分钟 · ${esc(t.style||'清晰教学风格')}</p>`:`<div class="slide-points">${s.points.map((p,i)=>`<div class="slide-point"><i>0${i+1}</i><span>${p}</span></div>`).join('')}</div>`}<div class="slide-footer"><span>一堂课 · ${esc(t.course||'教学课件')}</span><span>0${n+1} / 06</span></div></div><div class="slide-meta"><span>页面示意 · 非真实生成的PPTX</span><button class="text-button small" data-action="modify">修改这一页 ↗</button></div><section class="slide-notes"><h3>教师备注 <span class="muted">· 不展示给学生</span></h3><p>${s.notes}${t.changes?.[n]?.note?'<br>本次修改要求：'+esc(t.changes[n].note):''}</p></section></div></div><div class="artifact-strip"><span class="file-icon">PPTX</span><div><strong>${esc(t.title)}.pptx</strong><p>交付文件示意 · 版本 ${t.version||1} · 尚无真实文件</p></div><button data-action="artifact">查看下载交互</button></div></section>`;}
function resultSide(t){return `<aside class="result-sidebar"><section class="aside-note readiness-card"><h3>检查后，再带进课堂</h3><p>核对知识点、例题答案、备注，以及实际投影下的字体与排版。</p><label class="ready-check"><input id="reviewed" type="checkbox" ${t.reviewed?'checked':''}>我已核对课件内容与实际呈现</label><button class="primary side-action" data-action="ready" ${!t.reviewed||t.status==='ready'?'disabled':''}>${t.status==='ready'?'已标记可上课':'标记可上课（模拟）'}</button></section><section class="aside-note modification-card"><div class="change-editor" aria-labelledby="changeHeading"><h3 id="changeHeading">提出修改要求</h3><p>对照当前课件，直接说说希望怎么改。</p><label for="changeSlide">修改页面</label><select id="changeSlide">${slideExamples.map((s,i)=>`<option value="${i}" ${i===(t.selectedSlide||0)?'selected':''}>第 ${i+1} 页 · ${['封面','导入','概念','例题','练习','总结'][i]}</option>`).join('')}</select><label for="changeText">修改内容</label><textarea id="changeText" aria-label="修改要求" placeholder="例如：把这一页的例题换成生活情境，分三个步骤讲解。">${esc(t.changeDrafts?.[t.selectedSlide||0]||'')}</textarea><p class="helper">切换页面会保留未发送的文字。</p><button class="primary side-action" data-action="submit-change">提交修改（模拟）</button></div></section><section class="aside-note history-card"><h3>历史版本</h3>${Array.from({length:t.version||1},(_,i)=>{const v=(t.version||1)-i;return `<div class="version"><div><strong>版本 ${v}${v===(t.version||1)?' · 当前':''}</strong><span>${v>1?'指定页面修改':'首次课件示意'}</span></div><button class="text-button" data-action="version" data-index="${v}">查看</button></div>`;}).join('')}<p class="helper" style="margin-top:12px">修改生成新版本，旧版保留。</p></section><details class="review-controls"><summary>原型状态演示</summary><div><button data-action="simulate-fail">连接失败</button><button data-action="simulate-outline">待确认大纲</button></div></details></aside>`;}
function begin(generating=false){const t=task();const run=++runCounter;t.run=run;if(!generating){t.confirmed=false;t.reviewed=false;}t.status=generating?'generating':'submitting';route('feedback');if(location.hash.endsWith('/feedback'))renderFeedback();setTimeout(()=>{if(t.run!==run||!['generating','submitting'].includes(t.status))return;if(generating){if(t.pendingChange){const c=t.pendingChange;t.changes={...t.changes,[c.slide]:{title:c.title,note:c.note}};t.lastChange=c.note;if(t.changeDrafts)delete t.changeDrafts[c.slide];t.pendingChange=null;}t.status='complete';t.version=(t.version||0)+1;t.reviewed=false;}else t.status='outline';if(task()?.id===t.id&&location.hash.endsWith('/feedback'))renderFeedback();else if(location.hash==='#list')listRows();},generating?1800:1100);}
function stopRun(t){t.run=++runCounter;t.pendingChange=null;}
function editOutline(){const t=task();modal('调整教学大纲','<p>每行一个环节名称。时间分配保留为当前课时，修改后仍需确认。</p><textarea id="outlineEdit" aria-label="大纲环节名称">'+esc(getOutline(t).map(o=>o.title).join('\n'))+'</textarea>','<button data-action="close">取消</button><button class="primary" data-action="save-outline">保存大纲</button>');}
function positionChangeEditor(){
  const card=document.querySelector('.modification-card'),check=document.querySelector('.readiness-card'),preview=document.querySelector('.slide-meta'),side=document.querySelector('.result-sidebar');
  if(!card||!check||!preview||!side)return;
  if(window.matchMedia('(max-width:1000px)').matches){preview.after(check);check.after(card);}else{side.prepend(check);check.after(card);}
}
function modify(){$('changeText').focus({preventScroll:true});$('changeText').scrollIntoView({block:'nearest',behavior:'smooth'});}
async function act(action,el){const t=task();switch(action){
  case 'new':fresh=null;route('new');break;
  case 'list':route('list');break;
  case 'open':{const item=tasks.find(x=>x.id===el.dataset.id);currentId=item.id;route(item.status==='draft'?'requirements':item.method==='manual'?'manual':'feedback');break;}
  case 'help':modal('这份原型可以怎么体验','<ul><li>新建课件，填写四项必要信息；也可以一键填入虚构示例。</li><li>手动调用：复制完整任务文本，再体验外部制作记录。</li><li>平台调用：确认示例大纲，查看课件示意，提出单页修改。</li><li>右侧“原型状态演示”可切换失败、取消与大纲状态。</li></ul><div class="artifact-note">不连接WorkBuddy，不上传资料，不生成PPTX。任务仅在页面内存中，刷新后恢复初始示例。</div>');break;
  case 'close':close();break;
  case 'example':invalidate(t);Object.assign(t,{title:'条件概率：从直觉到判断',audience:'高一学生，已学习古典概型',minutes:45,content:'用抽球、天气与出行等生活情境理解条件概率，区分条件概率与独立事件。安排一道例题和两道课堂练习。',course:'数学 · 高一'});renderRequirements();toast('已填入虚构教学示例，可以继续修改。');break;
  case 'remove-file':invalidate(t);t.files.splice(Number(el.dataset.index),1);renderFiles();break;
  case 'save':ensureTask();toast('草稿已保存在当前页面，刷新后还原。');break;
  case 'requirements':route('requirements');break;
  case 'previous':if(['submitting','generating'].includes(t.status))break;route(Number(el.dataset.step)===2?'requirements':'method');break;
  case 'method':t.method=el.dataset.method;renderMethod();break;
  case 'start':if(t.method==='manual')route('manual');else begin(false);break;
  case 'copy':try{await navigator.clipboard.writeText(promptText(t));toast('完整任务已复制。请在 WorkBuddy 粘贴，并另外附上原始资料。');}catch{$('prompt').focus();$('prompt').select();toast('任务文本已选中，请按 Ctrl+C 复制。');}break;
  case 'download-text':{const blob=new Blob([promptText(t)],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(t.title||'课件')+'-任务文本.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已下载任务文本；参考资料需另外附上。');break;}
  case 'manual-sent':t.status='manual';renderManual();toast('已记录外部制作进度。请在 WorkBuddy 查看反馈。');break;
  case 'switch-manual':stopRun(t);t.method='manual';if(['submitting','generating'].includes(t.status))t.status='draft';route('manual');break;
  case 'inspect':modal('本次教学要求',`<p><strong>${esc(t.title)}</strong></p><p>${esc(t.audience)} · ${t.minutes} 分钟</p><div class="artifact-note">${esc(t.content||'根据附件整理')}</div><p>${t.files.length?'参考资料：'+t.files.map(f=>esc(f.name)).join('、'):'没有额外附件'}</p>`);break;
  case 'edit-outline':editOutline();break;
  case 'save-outline':{const lines=$('outlineEdit').value.split('\n').map(s=>s.trim()).filter(Boolean);if(lines.length!==5){toast('本示例保留5个教学环节，请每行填写一个名称。');break;}t.outlineTitles=lines;t.outlineRevision=(t.outlineRevision||0)+1;t.confirmed=false;close();renderFeedback();toast('大纲已调整，请确认后开始制作。');break;}
  case 'confirm-outline':t.confirmed=true;begin(true);break;
  case 'cancel':modal('取消本次制作？','<p>本轮制作将停止，尚未完成的修改不会应用。教学要求与已有版本会保留，之后可以重新发起。</p>','<button data-action="close" autofocus>继续等待</button><button class="danger" data-action="confirm-cancel">确认取消制作</button>');break;
  case 'confirm-cancel':close();if(!['submitting','generating'].includes(t.status)){toast('任务已经结束，已有结果已保留。');break;}stopRun(t);t.status='cancelled';renderFeedback();break;
  case 'retry':begin(!!t.confirmed);break;
  case 'simulate-fail':stopRun(t);t.status='failed';renderFeedback();break;
  case 'simulate-cancel':stopRun(t);t.status='cancelled';renderFeedback();break;
  case 'simulate-outline':stopRun(t);t.status='outline';t.confirmed=false;renderFeedback();break;
  case 'slide':t.selectedSlide=Number(el.dataset.index);renderFeedback();break;
  case 'modify':modify();break;
  case 'submit-change':{const text=$('changeText').value.trim();if(!text){$('changeText').focus();toast('请先写下希望修改的内容。');break;}t.changedSlide=Number($('changeSlide').value);t.selectedSlide=t.changedSlide;t.changedTitle=t.changedSlide===0?t.title:'根据课堂需要，重新组织这一页';t.pendingChange={slide:t.changedSlide,title:t.changedTitle,note:text};begin(true);break;}
  case 'artifact':modal('课件下载交互',`<p>${esc(t.title)}.pptx · 版本 ${t.version||1}</p><div class="artifact-note">正式功能将在这里下载WorkBuddy交付的PPTX与源文件。当前只有页面示意，没有真实PPTX，因此不提供伪造文件下载。</div><p>实际文件仍需在PowerPoint中检查排版、可编辑性和教师备注。</p>`);break;
  case 'version':modal('版本 '+el.dataset.index+' · 交付记录',`<p>此处展示历史版本入口，正式功能会保留原始文件与修改记录。</p><div class="artifact-note">当前版本：${t.version||1}<br>最近修改：${esc(t.lastChange||'首次课件示意')}<br>原型不保存真实历史文件。</div>`);break;
  case 'ready':if(!t.reviewed)break;t.status='ready';renderFeedback();toast('已标记可上课（模拟），不代表真实课件验收。');break;
  case 'import':modal('导回课件记录','<p>正式功能可保存外部制作的PPTX，方便以后找到。它不会自动变成平台内可逐对象编辑的内容。</p><label for="importFile">选择示例PPTX</label><input id="importFile" type="file" accept=".pptx"><div class="artifact-note">原型只记录文件名，不上传、不解析文件。</div>','<button data-action="close">取消</button><button class="primary" data-action="save-import">记录示例文件名</button>');break;
  case 'save-import':{const f=$('importFile').files[0];if(!f||!f.name.toLowerCase().endsWith('.pptx')){toast('请选择一份PPTX示例文件。');break;}t.importedName=f.name;close();renderManual();toast('已记录文件名，未读取或上传文件。');break;}
}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();toast('本原型只展示PPT管理，其他模块请在正式平台查看。');return;}const el=e.target.closest('[data-action]');if(el){e.preventDefault();act(el.dataset.action,el);}});
document.addEventListener('change',e=>{if(e.target.id==='reviewed'){task().reviewed=e.target.checked;const b=document.querySelector('[data-action="ready"]');if(b)b.disabled=!e.target.checked;}});
